using UnityEngine;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hud = GameObject.Find("HudRoot");
        if (hud == null) { result.Log("HudRoot missing"); return; }
        var doc = hud.GetComponent<UIDocument>();
        if (doc == null || doc.rootVisualElement == null) { result.Log("doc/root null"); return; }
        var root = doc.rootVisualElement;
        result.Log("root.classes: " + string.Join(",", root.GetClasses()));
        result.Log("root.childCount: " + root.childCount);
        for (int i = 0; i < root.childCount; i++)
        {
            var c = root[i];
            result.Log("  child[" + i + "]: name=" + c.name + " class=" + string.Join(",", c.GetClasses()));
        }
        // Check the StatusBar subtree.
        var sb = root.Q<VisualElement>("StatusBar");
        result.Log("StatusBar exists: " + (sb != null));
        if (sb != null)
        {
            result.Log("StatusBar.childCount: " + sb.childCount);
        }
        var tw = root.Q<VisualElement>("ToolbarContainer");
        result.Log("ToolbarContainer exists: " + (tw != null));
        var hp = root.Q<VisualElement>("HeldAssetPanel");
        result.Log("HeldAssetPanel exists: " + (hp != null));
    }
}
